contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run with parameters: whether to act as owner (true) or not (false), amount to send to C first, and amount to withdraw/send
    function run(bool asOwner, uint seedDeposit, uint actionAmount, bytes calldata data) public payable {
        // ensure this contract has enough balance to fund the initial deposit and any action send
        require(address(this).balance >= seedDeposit + actionAmount);

        // seedDeposit: send Ether into c to increase depositsCount and its balance
        if (seedDeposit > 0) {
            // send Ether to C using its receive() by using call with empty data
            (bool ok,) = address(c).call{value: seedDeposit}("");
            require(ok);
        }

        // read observables before the action
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Decide who will be the caller for the privileged actions.
        // If asOwner==true, InvMutTest (which deployed C) is the owner; otherwise we simulate a non-owner by performing a call from a different address
        bool reverted;
        if (asOwner) {
            // owner attempt: call withdraw(actionAmount)
            reverted = false;
            try c.withdraw(actionAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }

            // After owner call, owner must not have the call reverted arbitrarily: if it did not revert, c's balance must have decreased by at most actionAmount (transfer may send fewer if balance smaller)
            uint afterBalance = address(c).balance;
            uint expectedDecrease = beforeBalance >= actionAmount ? actionAmount : beforeBalance;

            // For the property check we will assert below
        } else {
            // non-owner attempt: perform the call via a low-level call from this contract but we need it to come from a different address.
            // We cannot change msg.sender in Solidity, so emulate by calling a function on c that is onlyOwner via a revert-catching low-level call from an external contract address.
            // To do that without deploying, call c.withdrawAll() via call and expect it to revert because only owner is InvMutTest (the deployer). Low-level call will return success=false on revert.
            (bool success,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
            reverted = !success;
        }

        // Read final observables
        uint afterDeposits = c.depositsCount();
        uint afterBalanceFinal = address(c).balance;

        // General rule asserted:
        // - depositsCount only increases when receive() is invoked (we sent seedDeposit earlier), so afterDeposits >= beforeDeposits.
        // - If action was by owner and did not revert, then c.balance decreased by at most actionAmount and depositsCount was not decreased by withdraw.
        // - If action was by non-owner, the privileged withdrawAll call must revert (i.e., reverted == true).
        if (asOwner) {
            uint beforeBalance = beforeBalance; // keep variable in scope for assert expression
            uint expectedDecrease = beforeBalance >= actionAmount ? actionAmount : beforeBalance;
            assert(afterDeposits >= beforeDeposits && beforeBalance - afterBalanceFinal <= expectedDecrease && reverted == false);
        } else {
            assert(afterDeposits >= beforeDeposits && reverted == true);
        }
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // seedDeposit: amount of wei to send to C via plain call (invokes receive)
    // withdrawAmount: amount owner will attempt to withdraw via withdraw(uint)
    // doWithdraw: whether to perform the owner withdraw (true) or skip it (false)
    function run(uint seedDeposit, uint withdrawAmount, bool doWithdraw) public payable {
        require(address(this).balance >= seedDeposit + (doWithdraw ? 0 : 0));

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Seed C by sending plain Ether to trigger receive(), if seedDeposit > 0
        if (seedDeposit > 0) {
            (bool ok,) = address(c).call{value: seedDeposit}("");
            require(ok);
        }

        // Perform owner withdraw attempt if requested. InvMutTest is owner since it deployed C.
        bool withdrawReverted;
        if (doWithdraw) {
            try c.withdraw(withdrawAmount) {
                withdrawReverted = false;
            } catch {
                withdrawReverted = true;
            }
        } else {
            withdrawReverted = false;
        }

        // Read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // Single assertion expressing the invariant:
        // 1) depositsCount never decreases (receive only increments), so afterDeposits >= beforeDeposits
        // 2) Any increase in depositsCount is at most 1 per successful receive call; here we sent at most one plain Ether call, so afterDeposits - beforeDeposits is either 0 or 1.
        // 3) withdraw (when attempted by owner) does not increase depositsCount, and if it succeeded (not reverted) then c.balance decreased by at most withdrawAmount.
        assert(
            afterDeposits >= beforeDeposits
            && (afterDeposits - beforeDeposits == 0 || afterDeposits - beforeDeposits == 1)
            && (afterDeposits >= beforeDeposits) // redundant but keeps logical grouping
            && (
                !doWithdraw
                || ( /* if withdraw attempted: depositsCount did not increase because of withdraw */ afterDeposits >= beforeDeposits && (
                    /* if withdraw succeeded, balance decrease is at most withdrawAmount */ withdrawReverted || (beforeBalance + seedDeposit - afterBalance <= withdrawAmount + 0)
                ))
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // seedDeposit: amount of wei to send to C via plain call (invokes receive)
    // withdrawAmount: amount owner will attempt to withdraw via withdraw(uint)
    // doWithdraw: whether to perform the owner withdraw (true) or skip it (false)
    function run(uint seedDeposit, uint withdrawAmount, bool doWithdraw) public payable {
        require(address(this).balance >= seedDeposit, "insufficient balance for seed");

        // Read before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // If requested, send Ether to C with a plain call to trigger receive()
        if (seedDeposit > 0) {
            (bool ok,) = address(c).call{value: seedDeposit}("");
            require(ok, "seed transfer failed");
        }

        // Attempt owner withdraw if requested. Must be a top-level state-changing call to c.
        bool withdrewSucceeded = true;
        if (doWithdraw) {
            try c.withdraw(withdrawAmount) {
                withdrewSucceeded = true;
            } catch {
                withdrewSucceeded = false;
            }
        }

        // Read after values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule (single assert):
        // 1) depositsCount never decreases.
        // 2) A single plain Ether transfer in this test can increase depositsCount by at most 1.
        // 3) withdraw(uint) (when called by owner) never increases depositsCount.
        // 4) If withdraw succeeded, the contract balance decreased by at most withdrawAmount.
        assert(
            // (1)
            afterDeposits >= beforeDeposits
            // (2) difference is 0 or 1
            && (afterDeposits - beforeDeposits == 0 || afterDeposits - beforeDeposits == 1)
            // (3) withdraw does not increase depositsCount: afterDeposits <= beforeDeposits + 1 (already implied) AND if doWithdraw then deposits increase is attributable only to the seed transfer, so no extra increase beyond 1
            && ( !doWithdraw || (afterDeposits - beforeDeposits <= 1) )
            // (4) if withdraw was attempted and succeeded, balance decreased by at most withdrawAmount
            && ( !doWithdraw || (!withdrewSucceeded) || ( beforeBalance + (seedDeposit) - afterBalance <= withdrawAmount ) )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
