    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        // record the deployer (owner) of c as this contract's address when c was deployed
        // The problem statement guarantees c was deployed before and owner == msg.sender at deployment,
        // and the checker will deploy c then deploy this test passing that c; we capture deployer as the current owner via public getter
