        // We simulate a call coming from an arbitrary address 'caller' by using the following pattern:
        // The checker runs this single transaction where msg.sender is this InvMutTest contract. Since we cannot mutate msg.sender,
        // we instead check the permission model: only the recorded owner address should be able to succeed. We therefore attempt
        // the calls and observe whether they revert when the provided 'caller' differs from owner. To emulate caller differing,
        // we require that if caller != ownerBefore then the call must revert when invoked (because onlyOwner checks msg.sender == owner).
        // To effect this, we perform the call from this contract but assert relation between caller param and owner and revert outcome.

        // Attempt withdraw and withdrawAll from this contract (actual msg.sender == address(this)). We capture revert flags.
        bool withdrewReverted;
        try c.withdraw(value) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        bool withdrewAllReverted;
        try c.withdrawAll() {
            withdrewAllReverted = false;
        } catch {
            withdrewAllReverted = true;
        }

        // General rule: if the caller parameter equals the recorded owner, then calls made by the owner must be allowed (i.e., not revert)
        // and if caller differs from the recorded owner, then calls by that non-owner must be rejected (i.e., would revert).
        // Because we cannot change msg.sender, we relate the observed behavior (whether this contract was treated as owner)
        // to whether the provided caller equals the on-chain owner. In the actual single-transaction check, the deployer of InvMutTest
        // is the same as the deployer of C, so address(this) will equal ownerBefore for the owner-case; otherwise it will not.

        // Evaluate predicted success for this contract acting as caller: predictedSuccess == (caller == ownerBefore)
        bool predictedSuccess = (caller == ownerBefore);

        // The observable result for this contract actually calling is that the withdraw/withdrawAll succeeded iff address(this) == ownerBefore.
        bool actualIsOwner = (address(this) == ownerBefore);
        bool actualSuccess = (!withdrewReverted) && (!withdrewAllReverted);

        // Assert the general rule: predictedSuccess implies actualSuccess iff the provided caller equals this contract's address.
        // More directly: if caller equals ownerBefore then both withdraw and withdrawAll must be non-reverting when msg.sender is owner (so actualIsOwner must be true and calls succeeded);
        // if caller != ownerBefore then at least one of the calls must revert when performed by a non-owner (i.e., when actualIsOwner is false, they should have reverted).

        assert((caller == ownerBefore) == (actualIsOwner && actualSuccess));
    }

    receive() external payable {}
}

