contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function taking inputs: target is ignored here, amount is used when calling payable functions
    function run(address caller, uint amount, bool callWithdrawAll, bool callWithdraw) public payable {
        require(address(this).balance >= amount);

        // Read observable state before the tested calls
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        // We need to simulate calls coming from either the owner (which is msg.sender at C construction)
        // or a non-owner. The InvMutTest was the deployer of C per the harness description, so InvMutTest is owner.
        // To test non-owner behavior, we'll use low-level call from this contract to invoke C but set msg.sender cannot be changed.
        // However the harness specifies that msg.sender is the InvMutTest for calls on c. So to create a non-owner call we must
        // rely on the fact that if the owner-only modifier requires msg.sender == owner (owner==InvMutTest), then only InvMutTest can succeed.
        // To model both cases, we treat the boolean flag 'caller' as: if caller == address(c) (i.e. equal to owner), we perform the call directly (owner); otherwise
        // we perform the call via a try/catch on c to observe whether it reverts. Since actual msg.sender cannot change, the only meaningful split is
        // whether the call is allowed (owner) or not. We'll interpret caller == address(this) as owner-case and caller != address(this) as non-owner-case.

        bool expectAllowed = (caller == address(this));

        bool revertedWithdrawAll = false;
        bool revertedWithdraw = false;

        // If requested, attempt withdrawAll and capture whether it reverts
        if (callWithdrawAll) {
            try c.withdrawAll() {
                revertedWithdrawAll = false;
            } catch {
                revertedWithdrawAll = true;
            }
        }

        // If requested, attempt withdraw(amount) and capture whether it reverts
        if (callWithdraw) {
            try c.withdraw(amount) {
                revertedWithdraw = false;
            } catch {
                revertedWithdraw = true;
            }
        }

        // Read observable state after the tested calls
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: If caller is not the owner (expectAllowed == false), then any withdraw/withdrawAll call must have reverted
        // and thus c's balance and depositsCount remain unchanged. If caller is owner, the calls may succeed (we don't assert specifics of balance change).
        if (!expectAllowed) {
            // both attempted calls that are owner-restricted must revert
            // If the test didn't attempt one of them, we don't require its revert flag; only the attempted ones must revert.
            bool attemptedAllMustRevert = !callWithdrawAll || revertedWithdrawAll;
            bool attemptedWithdrawMustRevert = !callWithdraw || revertedWithdraw;

            assert(attemptedAllMustRevert && attemptedWithdrawMustRevert && afterCount == beforeCount && afterBal == beforeBal);
        } else {
            // Owner case: don't assert specifics about results; but still must reach a single assert. We assert that at least one of the calls (if any) did not revert
            // or if no calls were attempted, state stayed the same.
            if (!callWithdrawAll && !callWithdraw) {
                assert(afterCount == beforeCount && afterBal == beforeBal);
            } else {
                bool someSucceeded = (callWithdrawAll && !revertedWithdrawAll) || (callWithdraw && !revertedWithdraw);
                assert(someSucceeded || (afterCount == beforeCount && afterBal == beforeBal));
            }
        }
    }

    // Allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

