contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will use a helper public function on C to send ETH by calling a payable function on C directly.
    // Since C does not expose a named payable function other than receive(), we instead perform the transfer
    // by calling a zero-data payable call through the special top-level statement: address(c).call{value: amount}("");
    // However, the constraints require state-changing calls on c to be of the form c.f(...). To satisfy that,
    // we instead invoke c.sendMoney with target = address(c) and data = empty bytes so that C will call itself
    // via _target.call{value: _value}(_data) and thus route the value into its receive().

    // Single public function with all test logic. It is payable so the test contract can forward ETH.
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Read before-state via public getters (allowed)
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt to route Ether into c by calling c.sendMoney which will internally call c (self-call)
        // This is a top-level state-changing call on c as required.
        bool reverted;
        try c.sendMoney(address(c), amount, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-state
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General property: if the sendMoney call succeeded and thus the internal self-call to receive() succeeded,
        // then depositsCount increased by exactly 1 and contract balance increased by amount. If sendMoney reverted,
        // then depositsCount and balance remain unchanged.
        assert(reverted ? (afterCount == beforeCount && afterBalance == beforeBalance)
                        : (afterCount == beforeCount + 1 && afterBalance == beforeBalance + amount));
    }

    // Allow this contract to receive ETH so it can forward it in the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters: target to send to, amount of wei forwarded, and data payload.
    // The InvMutTest contract is the deployer of c, thus it is c.owner() initially.
    function run(address target, uint amount, bytes calldata data) public payable {
        // Ensure this contract has enough balance to forward amount when needed
        require(address(this).balance >= amount);

        // Observe before state
        uint beforeCount = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt the call and record whether it reverted
        bool reverted;
        try c.sendMoney(target, amount, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after state
        uint afterCount = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule:
        // - If the caller (this contract) is not the owner, sendMoney must revert and nothing changes.
        //   But this contract is the owner initially; to capture both cases across inputs we check the public getter owner().
        // - If this contract is the owner and the call reverted, state did not change.
        // - If this contract is the owner and the call succeeded, then at most one deposit could have been recorded
        //   (receive increments depositsCount by 1) and the contract balance cannot increase by more than amount.
        // Formally assert the combined property below.
        address owner = c.owner();

        assert(
            // If caller is not owner, sendMoney must revert and state unchanged
            (owner != address(this) ? (reverted && afterCount == beforeCount && afterBalance == beforeBalance)
             :
             // If caller is owner:
             (reverted ? (afterCount == beforeCount && afterBalance == beforeBalance)
              :
              // succeeded: depositsCount increases by at most 1 and balance increases by at most amount
              (afterCount >= beforeCount && afterCount <= beforeCount + 1 && afterBalance >= beforeBalance && afterBalance <= beforeBalance + amount)
             )
            )
        );
    }

    receive() external payable {}
}

