        bool reverted;
        // We explicitly perform a low-level call with empty calldata to trigger receive
        (reverted,) = address(c).call{value: sendAmount}("");

        // read after-values
        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // If the call reverted, depositsCount must be unchanged and balance unchanged.
        // If the call did not revert, depositsCount increases by exactly 1 and balance increases by sendAmount.
